import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.k9nOhppk.js";const u=JSON.parse('{"title":"Tutorial","description":"","frontmatter":{"title":"Tutorial"},"headers":[],"relativePath":"tutorial/index.md","filePath":"tutorial/index.md","lastUpdated":1791864160000}'),i={name:"tutorial/index.md"};function r(n,e,l,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="tutorial" tabindex="-1">Tutorial <a class="header-anchor" href="#tutorial" aria-label="Permalink to &quot;Tutorial&quot;">​</a></h1><p>This tutorial teaches Eyelang by writing small programs, from plain values up to a job that waits fifteen minutes and survives a restart. It assumes you can program in some other language, and that you have <code>eye</code> installed (<a href="/quickstart">Quickstart</a>).</p><h2 id="what-you-ll-build" tabindex="-1">What you&#39;ll build <a class="header-anchor" href="#what-you-ll-build" aria-label="Permalink to &quot;What you&#39;ll build&quot;">​</a></h2><p>The examples follow a small shop:</p><ol><li><a href="/tutorial/values-and-functions">Values and functions</a>: prices and a shopping basket, with <code>let</code>, functions, lists, pipes and your first tests.</li><li><a href="/tutorial/types-and-matching">Types and matching</a>: a to-do list, with records, variant types, exhaustive <code>match</code>, <code>Option</code> and methods.</li><li><a href="/tutorial/errors">Errors</a>: reading an order and taking it from the stock, with <code>Result</code>, <code>?</code> and <code>mut</code>.</li><li><a href="/tutorial/an-entity">An entity</a>: the shop&#39;s shelves as entities, which own their state and change it in transactions.</li><li><a href="/tutorial/a-job-that-waits">A job that waits</a>: a hold on stock that ends after fifteen minutes, unless the order is paid for first.</li><li><a href="/tutorial/approvals">All together: approvals</a>: a larger program that uses everything above.</li></ol><p>Each page takes five to ten minutes to read and builds on the one before it.</p><h2 id="how-the-pages-work" tabindex="-1">How the pages work <a class="header-anchor" href="#how-the-pages-work" aria-label="Permalink to &quot;How the pages work&quot;">​</a></h2><p>Each page has one program behind it, in <a href="https://github.com/ruxxzebre/eyelang/tree/dev/docs/tutorial/code" target="_blank" rel="noreferrer"><code>docs/tutorial/code/</code></a>, one directory per page. The code you see on a page is taken straight from that program, and its <code>test</code> blocks check everything the page says. The test suite runs every one of them, so the examples always work with the current <code>eye</code>.</p><p>To follow along, run a page&#39;s program yourself from the repository&#39;s root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">eye</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/tutorial/code/values-and-functions</span></span></code></pre></div><p>Or copy a page&#39;s code into a directory of your own with an empty <code>eye.toml</code>, and change it.</p><p>Each page ends with links to the <a href="/reference/language/">language reference</a>, which states the full rules. The tutorial shows the common cases and leaves the rest to it.</p>',12)])])}const g=a(i,[["render",r]]);export{u as __pageData,g as default};
